package goemit

// nodeHTTP2StreamRuntime ports the HTTP/2 PUSH, extension-frame, and outbound
// stream operations from Bun's connection engine.
const nodeHTTP2StreamRuntime = `
func (connection *tsHTTP2Connection)handlePushPromise(sink tsHTTP2Sink,header tsHTTP2FrameHeader,payload []byte)bool{if connection.isServer{connection.sendGoAway(sink,tsHTTP2ErrorProtocol,[]byte("server received PUSH_PROMISE"));return true};if connection.localSettings.enablePush==0{connection.sendGoAway(sink,tsHTTP2ErrorProtocol,[]byte("PUSH_PROMISE with push disabled"));return true};offset,end:=0,len(payload);if tsHTTP2HasFrameFlag(header.flags,8){if len(payload)==0{connection.sendGoAway(sink,tsHTTP2ErrorFrameSize,[]byte("PUSH_PROMISE padded but empty"));return true};padding:=int(payload[0]);offset=1;if offset+padding>end{connection.sendGoAway(sink,tsHTTP2ErrorProtocol,[]byte("PUSH_PROMISE padding too large"));return true};end-=padding};if offset+4>end{connection.sendGoAway(sink,tsHTTP2ErrorFrameSize,[]byte("PUSH_PROMISE missing promised id"));return true};promised:=binary.BigEndian.Uint32(payload[offset:offset+4])&0x7fffffff;offset+=4;if promised==0||promised&1==1||connection.streams[promised]!=nil{connection.sendGoAway(sink,tsHTTP2ErrorProtocol,[]byte("PUSH_PROMISE invalid promised stream id"));return true};stream:=tsHTTP2NewProtocolStream(connection.remoteSettings.initialWindowSize,connection.localSettings.initialWindowSize);stream.state=tsHTTP2StreamReservedRemote;connection.streams[promised]=stream;if promised>connection.lastStreamID{connection.lastStreamID=promised};connection.headerBlock=append(connection.headerBlock[:0],payload[offset:end]...);meta:=tsHTTP2HeaderBlockMeta{target:promised,pushParent:header.streamID,hasPushParent:true,isRequest:true,disposition:tsHTTP2BlockDeliver};return connection.finishOrParkHeaderBlock(sink,header,meta)}
func (connection *tsHTTP2Connection)handleAltSvc(sink tsHTTP2Sink,header tsHTTP2FrameHeader,payload []byte)bool{if len(payload)<2{return false};originLength:=int(binary.BigEndian.Uint16(payload[:2]));if 2+originLength>len(payload){return false};origin,value:=payload[2:2+originLength],payload[2+originLength:];if connection.isServer||(header.streamID==0&&len(origin)==0)||(header.streamID!=0&&len(origin)!=0){return false};sink.onAltSvc(header.streamID,origin,value);return false}
func (connection *tsHTTP2Connection)handleOrigin(sink tsHTTP2Sink,header tsHTTP2FrameHeader,payload []byte)bool{if header.streamID!=0||connection.isServer{return false};sink.onOrigin(payload);return false}
func (connection *tsHTTP2Connection)beginHeaderBlock(){connection.encBuf=connection.encBuf[:0];var update [6]byte;if count:=connection.hpack.takePendingSizeUpdate(update[:],0);count>0{connection.encBuf=append(connection.encBuf,update[:count]...)}}
func (connection *tsHTTP2Connection)encodeHeader(name,value []byte,neverIndexed bool)bool{old:=len(connection.encBuf);connection.encBuf=append(connection.encBuf,make([]byte,len(name)+len(value)+16)...);written,errCode:=connection.hpack.encode(name,value,neverIndexed,connection.encBuf,old);if errCode!=0{connection.encBuf=connection.encBuf[:old];return false};connection.encBuf=connection.encBuf[:old+written];return true}
type tsHTTP2Priority struct{ parent uint32; weight uint8; exclusive bool }
func (connection *tsHTTP2Connection)sendHeaderBlock(sink tsHTTP2Sink,streamID uint32,endStream bool,priority *tsHTTP2Priority,paddingStrategy uint8){block:=connection.encBuf;connection.encBuf=nil;maxFrame:=max(int(connection.remoteSettings.maxFrameSize),1);priorityBytes:=0;flags:=uint8(0);prefix:=[]byte(nil);if priority!=nil{priorityBytes=5;flags|=32;dependency:=priority.parent&0x7fffffff;if priority.exclusive{dependency|=0x80000000};prefix=make([]byte,5);binary.BigEndian.PutUint32(prefix,dependency);prefix[4]=priority.weight-1};available:=max(maxFrame-priorityBytes,0);padding:=uint8(0);if len(block)<available{padding=tsHTTP2PaddingFor(paddingStrategy,len(block),available-1)};paddingOverhead:=0;if padding>0{paddingOverhead=1+int(padding);flags|=8};firstLength:=min(len(block),max(available-paddingOverhead,0));if firstLength==len(block){flags|=4}else{padding=0;paddingOverhead=0;flags &^=8;firstLength=available};if endStream{flags|=1};payload:=make([]byte,0,priorityBytes+paddingOverhead+firstLength);if padding>0{payload=append(payload,padding)};payload=append(payload,prefix...);payload=append(payload,block[:firstLength]...);if padding>0{payload=append(payload,make([]byte,int(padding))...)};connection.writeFrame(sink,1,flags,streamID,payload);offset:=firstLength;for offset<len(block){length:=min(len(block)-offset,maxFrame);continuationFlags:=uint8(0);if offset+length==len(block){continuationFlags=4};connection.writeFrame(sink,9,continuationFlags,streamID,block[offset:offset+length]);offset+=length};connection.encBuf=block[:0];stream:=connection.streams[streamID];if stream==nil{stream=tsHTTP2NewProtocolStream(connection.remoteSettings.initialWindowSize,connection.localSettings.initialWindowSize);connection.streams[streamID]=stream};event:=tsHTTP2EventSendHeaders;if endStream{event=tsHTTP2EventSendHeadersEndStream};if next,err:=tsHTTP2Transition(stream.state,event);err==0{stream.state=next};if streamID>connection.lastStreamID{connection.lastStreamID=streamID}}
func tsHTTP2PaddingFor(strategy uint8,frameLen,maxLen int)uint8{if maxLen<frameLen{return 0};switch strategy{case 1:diff:=(frameLen+9)%8;if diff==0{return 0};padded:=min(frameLen+(8-diff),maxLen);return uint8(min(max(padded-frameLen,0),255));case 2:return uint8(min(maxLen-frameLen,255));default:return 0}}
func (connection *tsHTTP2Connection)sendData(sink tsHTTP2Sink,streamID uint32,data []byte,endStream bool,paddingStrategy uint8)int{connectionWindow:=connection.sendWindow.available();streamWindow:=int64(0);if stream:=connection.streams[streamID];stream!=nil{streamWindow=stream.sendWindow.available()};maxFrame:=int64(connection.remoteSettings.maxFrameSize);allowed:=max(connectionWindow,0);allowed=min(allowed,streamWindow);allowed=min(allowed,maxFrame);toSend:=min(int(allowed),len(data));sendAll:=toSend==len(data);if toSend==0&&!(len(data)==0&&endStream){return 0};padding:=uint8(0);if toSend>0&&paddingStrategy!=0{padding=tsHTTP2PaddingFor(paddingStrategy,toSend,max(toSend,int(allowed))-1)};payloadSize:=toSend;if padding>0{payloadSize+=1+int(padding)};flags:=uint8(0);if endStream&&sendAll{flags|=1};payload:=make([]byte,0,payloadSize);if padding>0{flags|=8;payload=append(payload,padding)};payload=append(payload,data[:toSend]...);if padding>0{payload=append(payload,make([]byte,int(padding))...)};connection.writeFrame(sink,0,flags,streamID,payload);connection.sendWindow.consume(int64(payloadSize));if stream:=connection.streams[streamID];stream!=nil{stream.sendWindow.consume(int64(payloadSize));if endStream&&sendAll{if next,err:=tsHTTP2Transition(stream.state,tsHTTP2EventSendEndStream);err==0{stream.state=next}}};return toSend}
func (connection *tsHTTP2Connection)closeStream(streamID uint32){delete(connection.streams,streamID)}
func (connection *tsHTTP2Connection)replenishStream(sink tsHTTP2Sink,streamID uint32){stream:=connection.streams[streamID];if stream==nil||stream.state==tsHTTP2StreamClosed||!stream.recvWindow.needsUpdate(){return};if increment:=stream.recvWindow.takeUpdate();increment>0{connection.sendWindowUpdate(sink,streamID,increment)}}
func (connection *tsHTTP2Connection)sendPushPromise(sink tsHTTP2Sink,parentID,promisedID uint32){block:=connection.encBuf;connection.encBuf=nil;maxFrame:=max(int(connection.remoteSettings.maxFrameSize),5);firstCapacity:=maxFrame-4;firstLength:=min(len(block),firstCapacity);first:=make([]byte,4+firstLength);binary.BigEndian.PutUint32(first,promisedID&0x7fffffff);copy(first[4:],block[:firstLength]);flags:=uint8(0);if firstLength==len(block){flags=4};connection.writeFrame(sink,5,flags,parentID,first);offset:=firstLength;for offset<len(block){length:=min(len(block)-offset,maxFrame);continuationFlags:=uint8(0);if offset+length==len(block){continuationFlags=4};connection.writeFrame(sink,9,continuationFlags,parentID,block[offset:offset+length]);offset+=length};connection.encBuf=block[:0];stream:=connection.streams[promisedID];if stream==nil{stream=tsHTTP2NewProtocolStream(connection.remoteSettings.initialWindowSize,connection.localSettings.initialWindowSize);connection.streams[promisedID]=stream};stream.state=tsHTTP2StreamReservedLocal;if promisedID>connection.lastStreamID{connection.lastStreamID=promisedID}}
`
